//! Handshake frames: the first exchange on every connection, and the bare
//! error frame that announces a connection-level close.
//!
//! They are part of remote protocol v1: their schema and golden frames are
//! generated by [`crate::remote::contract`] and committed next to the session
//! frames under `docs/remote-protocol/v1/`. Everything after a successful
//! handshake is a [`crate::remote::RemoteRequest`] handed to
//! [`super::router::FrameRouter`].
//!
//! Every frame is one JSON object in one WebSocket text frame, tagged by
//! `type`. Unknown fields are ignored, so fields can be added.

use super::devices::DeviceProfile;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::fmt;

/// Version of the handshake frames below.
pub const HANDSHAKE_PROTOCOL_VERSION: u32 = 1;

/// The `wire_names` a device sends to read and write every frame after the
/// handshake with "thread" where protocol v1 says "session" (`thread_id`,
/// `list_threads`, `kind: "threads"`, …; see
/// [`super::wire_names`]). A gateway that understands it echoes it in its
/// `paired` or `authenticated` frame; an older gateway ignores the field and
/// the device keeps the v1 names. Devices that do not ask get the v1 names.
pub const WIRE_NAMES_THREAD: &str = "thread";

/// Largest handshake frame accepted from an unauthenticated socket.
pub const MAX_HANDSHAKE_FRAME_BYTES: usize = 8 * 1024;

/// A pairing credential, manual code or device token. Serializes as a plain
/// string; `Debug` never prints the value, so it cannot reach logs or error
/// strings through a derived impl.
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(transparent)]
pub struct Secret(String);

impl Secret {
    pub fn new(value: impl Into<String>) -> Self {
        Self(value.into())
    }

    /// The raw value, for comparison, hashing or showing it to its owner.
    pub fn expose(&self) -> &str {
        &self.0
    }
}

impl fmt::Debug for Secret {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("Secret(<redacted>)")
    }
}

/// Which representation of a pairing challenge the device presents.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum PairingMethod {
    /// The high-entropy credential carried by the QR payload.
    Credential,
    /// The short code typed by hand next to the address.
    Code,
}

/// First frame from a device. Anything else closes the connection.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum HandshakeRequest {
    /// Ask the host's owner to let this device pair. Carries no secret. The
    /// socket stays open for the answer (`connect_pending`, then
    /// `connect_approved`, `connect_denied` or `connect_expired`); after
    /// `connect_approved` it sends one `pair` frame with `method: "code"` and
    /// the code the owner reads off the host. Only gateways that list
    /// `connect_requests` in their Bonjour `caps` take it.
    ConnectRequest {
        protocol_version: u32,
        /// A label chosen by the device, shown to the owner. Never an identity.
        device_name: String,
        /// What the device runs on, for the owner: `ios`, `android`,
        /// `macos`, `windows`, `linux`, ….
        platform: String,
        /// As in `pair`. A new request from the same address and install
        /// replaces the one still open, so a reconnecting app does not wait
        /// for its old request to expire.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        install_id: Option<String>,
        /// As in `pair`. Recorded with the device when it pairs, over
        /// whatever its `pair` frame says, because it is what the owner saw.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        device_kind: Option<String>,
        /// As in `pair`.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        host_id: Option<String>,
    },
    /// Exchange a pairing challenge for a device token.
    Pair {
        protocol_version: u32,
        method: PairingMethod,
        secret: Secret,
        /// A label chosen by the device. Never an identity.
        device_name: String,
        /// A random identifier the app generates once per install and keeps.
        /// Pairing again with the same one replaces that install's earlier
        /// device record and revokes its token, instead of adding a record.
        /// Not tied to the user; ignored unless it is 16 to 128 printable
        /// ASCII characters. Older apps leave it out.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        install_id: Option<String>,
        /// `"thread"` asks for the thread names on the wire; see [`WIRE_NAMES_THREAD`].
        #[serde(default, skip_serializing_if = "Option::is_none")]
        wire_names: Option<String>,
        /// What the device is: `phone`, `desktop` (the desktop app on
        /// another machine) or `cli`. Absent, or a kind this gateway does
        /// not know, is a phone. A label for the owner, not a permission.
        /// Gateways that list `desktops` in their capabilities record it.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        device_kind: Option<String>,
        /// What the device runs on: `ios`, `android`, `macos`, `windows`,
        /// `linux`, …. Absent is `unknown`.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        platform: Option<String>,
        /// The stable identifier of the machine a desktop app or command
        /// line runs on, which the owner may pair with in turn. Ignored
        /// unless it is 16 to 128 printable ASCII characters.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        host_id: Option<String>,
    },
    /// Present a device token obtained from an earlier `paired` frame.
    Authenticate {
        protocol_version: u32,
        device_id: String,
        token: Secret,
        /// `"thread"` asks for the thread names on the wire; see [`WIRE_NAMES_THREAD`].
        #[serde(default, skip_serializing_if = "Option::is_none")]
        wire_names: Option<String>,
    },
}

impl HandshakeRequest {
    /// Whether the device asked for the thread names on the wire.
    pub fn wants_thread_names(&self) -> bool {
        match self {
            Self::Pair { wire_names, .. } | Self::Authenticate { wire_names, .. } => {
                wire_names.as_deref() == Some(WIRE_NAMES_THREAD)
            }
            Self::ConnectRequest { .. } => false,
        }
    }

    /// What a `connect_request` or `pair` frame says the device is, kept to
    /// what is usable. An `authenticate` frame says nothing: the device was
    /// recorded when it paired.
    pub fn device_profile(&self) -> DeviceProfile {
        match self {
            Self::ConnectRequest {
                platform,
                device_kind,
                host_id,
                ..
            } => {
                DeviceProfile::from_wire(device_kind.as_deref(), Some(platform), host_id.as_deref())
            }
            Self::Pair {
                device_kind,
                platform,
                host_id,
                ..
            } => DeviceProfile::from_wire(
                device_kind.as_deref(),
                platform.as_deref(),
                host_id.as_deref(),
            ),
            Self::Authenticate { .. } => DeviceProfile::default(),
        }
    }

    /// Parse a first frame. The version is checked before the shape, so a
    /// newer client gets `unsupported_version` rather than `invalid_frame`.
    pub fn parse(text: &str) -> Result<Self, HandshakeResponse> {
        if text.len() > MAX_HANDSHAKE_FRAME_BYTES {
            return Err(HandshakeResponse::error(
                ErrorCode::FrameTooLarge,
                "handshake frame is too large",
            ));
        }
        let invalid = || {
            HandshakeResponse::error(
                ErrorCode::InvalidFrame,
                "first frame must be a pair or authenticate request",
            )
        };
        let value: serde_json::Value = serde_json::from_str(text).map_err(|_| invalid())?;
        let version = value.get("protocol_version").and_then(|v| v.as_u64());
        if version.is_some_and(|version| version != u64::from(HANDSHAKE_PROTOCOL_VERSION)) {
            return Err(HandshakeResponse::error(
                ErrorCode::UnsupportedVersion,
                format!("this gateway speaks protocol version {HANDSHAKE_PROTOCOL_VERSION}"),
            ));
        }
        // serde_json errors can quote input; never forward them to the peer or a log.
        serde_json::from_value(value).map_err(|_| invalid())
    }
}

/// Frames the gateway sends during the handshake, and the error frame that
/// precedes a close. After authentication an `error` frame is never the
/// answer to a request: those are `response` frames carrying the request ID.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum HandshakeResponse {
    /// The connection request is in front of the host's owner. Wait on the
    /// same socket, sending nothing but pings, for the answer.
    ConnectPending {
        request_id: String,
        /// Time the owner has to answer.
        expires_in_secs: u64,
    },
    /// The owner accepted and the host shows a code. Send one `pair` frame
    /// with `method: "code"` and that code within `expires_in_secs`. Only
    /// this socket can redeem it.
    ConnectApproved {
        request_id: String,
        /// Digits in the code, without its separator.
        code_length: u32,
        expires_in_secs: u64,
    },
    /// The owner denied the request. The connection closes.
    ConnectDenied,
    /// Nobody answered in time, the code was not sent in time, or a newer
    /// code on the host replaced it. The connection closes; ask again.
    ConnectExpired,
    /// Pairing succeeded. `token` is shown exactly once; the connection is
    /// authenticated as this device from here on.
    Paired {
        protocol_version: u32,
        gateway_id: String,
        instance_id: String,
        device_id: String,
        device_name: String,
        token: Secret,
        /// The host's own name, for display. A label, not an identity.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        host_name: Option<String>,
        /// When this pairing stops being accepted, RFC 3339 in UTC. The device
        /// pairs again after it.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        expires_at: Option<String>,
        /// `"thread"` when the gateway accepted the device's request for the
        /// thread names; absent means the v1 names.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        wire_names: Option<String>,
    },
    /// The device token was accepted.
    Authenticated {
        protocol_version: u32,
        gateway_id: String,
        instance_id: String,
        device_id: String,
        device_name: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        host_name: Option<String>,
        /// When this pairing stops being accepted, RFC 3339 in UTC. The device
        /// pairs again after it.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        expires_at: Option<String>,
        /// `"thread"` when the gateway accepted the device's request for the
        /// thread names; absent means the v1 names.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        wire_names: Option<String>,
    },
    Error {
        code: ErrorCode,
        message: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        retry_after_secs: Option<u64>,
    },
}

impl HandshakeResponse {
    pub fn error(code: ErrorCode, message: impl Into<String>) -> Self {
        Self::Error {
            code,
            message: message.into(),
            retry_after_secs: None,
        }
    }

    pub fn to_text(&self) -> String {
        serde_json::to_string(self).expect("handshake frames always serialize")
    }

    /// Confirm the thread names in a `paired` or `authenticated` frame.
    pub fn confirm_thread_names(&mut self) {
        if let Self::Paired { wire_names, .. } | Self::Authenticated { wire_names, .. } = self {
            *wire_names = Some(WIRE_NAMES_THREAD.to_owned());
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum ErrorCode {
    /// The frame is not JSON, not text, or not a known handshake request.
    InvalidFrame,
    FrameTooLarge,
    UnsupportedVersion,
    /// No frame arrived within the handshake deadline.
    HandshakeTimeout,
    /// Wrong, expired, exhausted or already used pairing secret. The cases
    /// are deliberately indistinguishable.
    PairingFailed,
    /// Too many failed pairing attempts on this host; see `retry_after_secs`.
    RateLimited,
    /// Unknown device, revoked device or wrong token; indistinguishable.
    Unauthorized,
    /// The gateway is at its connection or device limit.
    Busy,
    /// The host holds as many connection requests as it takes, or this
    /// address already has one open. Retry later.
    ConnectBusy,
    /// This address was denied a moment ago; see `retry_after_secs`.
    ConnectRateLimited,
    /// The device was revoked while connected. Do not reconnect.
    Revoked,
    /// The device did not read fast enough and its queue overflowed.
    SlowConsumer,
    /// Nothing was received from the device for too long.
    IdleTimeout,
    ShuttingDown,
    /// Sent only by a gateway without session routing; kept for
    /// compatibility.
    NotImplemented,
    Internal,
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::remote_gateway::devices::DeviceKind;

    #[test]
    fn connect_request_parses_and_responses_serialize() {
        let text = r#"{"type":"connect_request","protocol_version":1,"device_name":"Lars's iPhone","platform":"ios","install_id":"install-12345678"}"#;
        assert!(
            matches!(HandshakeRequest::parse(text), Ok(HandshakeRequest::ConnectRequest { device_name, platform, .. }) if device_name == "Lars's iPhone" && platform == "ios")
        );
        assert_eq!(
            HandshakeResponse::ConnectPending {
                request_id: "r1".into(),
                expires_in_secs: 120
            }
            .to_text(),
            r#"{"type":"connect_pending","request_id":"r1","expires_in_secs":120}"#
        );
        assert_eq!(
            HandshakeResponse::ConnectApproved {
                request_id: "r1".into(),
                code_length: 8,
                expires_in_secs: 120
            }
            .to_text(),
            r#"{"type":"connect_approved","request_id":"r1","code_length":8,"expires_in_secs":120}"#
        );
        // `install_id` is optional both ways.
        let bare = r#"{"type":"connect_request","protocol_version":1,"device_name":"phone","platform":"android"}"#;
        let parsed = HandshakeRequest::parse(bare).unwrap();
        assert_eq!(serde_json::to_string(&parsed).unwrap(), bare);
        assert!(!parsed.wants_thread_names());
        assert_eq!(
            HandshakeResponse::ConnectDenied.to_text(),
            r#"{"type":"connect_denied"}"#
        );
        assert_eq!(
            HandshakeResponse::ConnectExpired.to_text(),
            r#"{"type":"connect_expired"}"#
        );
    }

    #[test]
    fn device_fields_round_trip_and_older_frames_mean_a_phone() {
        let connect = r#"{"type":"connect_request","protocol_version":1,"device_name":"Lars's PC","platform":"windows","install_id":"install-12345678","device_kind":"desktop","host_id":"host-0123456789abcdef"}"#;
        let parsed = HandshakeRequest::parse(connect).unwrap();
        assert_eq!(serde_json::to_string(&parsed).unwrap(), connect);
        let profile = parsed.device_profile();
        assert_eq!(profile.kind, DeviceKind::Desktop);
        assert_eq!(profile.platform, "windows");
        assert_eq!(profile.host_id.as_deref(), Some("host-0123456789abcdef"));

        let pair = r#"{"type":"pair","protocol_version":1,"method":"code","secret":"1234-5678","device_name":"box","device_kind":"cli","platform":"linux","host_id":"host-fedcba9876543210"}"#;
        let parsed = HandshakeRequest::parse(pair).unwrap();
        assert_eq!(serde_json::to_string(&parsed).unwrap(), pair);
        let profile = parsed.device_profile();
        assert_eq!(profile.kind, DeviceKind::Cli);
        assert_eq!(profile.platform, "linux");

        // Frames from apps that predate the fields: a phone on an unknown platform.
        let old = HandshakeRequest::parse(
            r#"{"type":"pair","protocol_version":1,"method":"code","secret":"1234-5678","device_name":"phone"}"#,
        )
        .unwrap();
        assert_eq!(old.device_profile(), DeviceProfile::default());
        let old = HandshakeRequest::parse(
            r#"{"type":"connect_request","protocol_version":1,"device_name":"phone","platform":"ios"}"#,
        )
        .unwrap();
        assert_eq!(old.device_profile().kind, DeviceKind::Phone);
        assert_eq!(old.device_profile().platform, "ios");
        // A kind from a newer client still parses; it is recorded as a phone.
        let newer = HandshakeRequest::parse(
            r#"{"type":"pair","protocol_version":1,"method":"code","secret":"1","device_name":"x","device_kind":"link"}"#,
        )
        .unwrap();
        assert_eq!(newer.device_profile().kind, DeviceKind::Phone);
    }

    #[test]
    fn request_wire_shapes_are_stable() {
        let pair = HandshakeRequest::Pair {
            protocol_version: 1,
            method: PairingMethod::Code,
            secret: Secret::new("1234-5678"),
            device_name: "phone".into(),
            install_id: None,
            wire_names: None,
            device_kind: None,
            platform: None,
            host_id: None,
        };
        assert_eq!(
            serde_json::to_string(&pair).unwrap(),
            r#"{"type":"pair","protocol_version":1,"method":"code","secret":"1234-5678","device_name":"phone"}"#
        );
        let authenticate = HandshakeRequest::Authenticate {
            protocol_version: 1,
            device_id: "0011223344556677".into(),
            token: Secret::new("tok"),
            wire_names: None,
        };
        assert_eq!(
            serde_json::to_string(&authenticate).unwrap(),
            r#"{"type":"authenticate","protocol_version":1,"device_id":"0011223344556677","token":"tok"}"#
        );
        assert_eq!(
            HandshakeRequest::parse(&serde_json::to_string(&pair).unwrap()).unwrap(),
            pair
        );
    }

    #[test]
    fn response_wire_shapes_are_stable() {
        let paired = HandshakeResponse::Paired {
            protocol_version: 1,
            gateway_id: "gw".into(),
            instance_id: "inst".into(),
            device_id: "dev".into(),
            device_name: "phone".into(),
            token: Secret::new("tok"),
            host_name: None,
            expires_at: None,
            wire_names: None,
        };
        assert_eq!(
            paired.to_text(),
            r#"{"type":"paired","protocol_version":1,"gateway_id":"gw","instance_id":"inst","device_id":"dev","device_name":"phone","token":"tok"}"#
        );
        let authenticated = HandshakeResponse::Authenticated {
            protocol_version: 1,
            gateway_id: "gw".into(),
            instance_id: "inst".into(),
            device_id: "dev".into(),
            device_name: "phone".into(),
            host_name: None,
            expires_at: None,
            wire_names: None,
        };
        assert_eq!(
            authenticated.to_text(),
            r#"{"type":"authenticated","protocol_version":1,"gateway_id":"gw","instance_id":"inst","device_id":"dev","device_name":"phone"}"#
        );
        assert_eq!(
            HandshakeResponse::error(ErrorCode::PairingFailed, "no").to_text(),
            r#"{"type":"error","code":"pairing_failed","message":"no"}"#
        );
        let limited = HandshakeResponse::Error {
            code: ErrorCode::RateLimited,
            message: "wait".into(),
            retry_after_secs: Some(30),
        };
        assert_eq!(
            limited.to_text(),
            r#"{"type":"error","code":"rate_limited","message":"wait","retry_after_secs":30}"#
        );
    }

    fn code_of(result: Result<HandshakeRequest, HandshakeResponse>) -> ErrorCode {
        match result {
            Err(HandshakeResponse::Error { code, .. }) => code,
            other => panic!("expected an error frame, got {other:?}"),
        }
    }

    #[test]
    fn parse_rejects_other_versions_shapes_and_oversized_frames() {
        assert_eq!(
            code_of(HandshakeRequest::parse(
                r#"{"type":"authenticate","protocol_version":2,"device_id":"d","token":"t"}"#
            )),
            ErrorCode::UnsupportedVersion
        );
        // A newer shape still reports the version, not a parse failure.
        assert_eq!(
            code_of(HandshakeRequest::parse(
                r#"{"type":"hello","protocol_version":9}"#
            )),
            ErrorCode::UnsupportedVersion
        );
        for invalid in [
            "",
            "not json",
            "[]",
            r#"{"type":"list_sessions","protocol_version":1}"#,
            r#"{"type":"authenticate","device_id":"d","token":"t"}"#,
            r#"{"type":"pair","protocol_version":1,"method":"guess","secret":"s","device_name":"n"}"#,
        ] {
            assert_eq!(
                code_of(HandshakeRequest::parse(invalid)),
                ErrorCode::InvalidFrame,
                "{invalid}"
            );
        }
        let oversized = format!(
            r#"{{"type":"authenticate","protocol_version":1,"device_id":"d","token":"{}"}}"#,
            "a".repeat(MAX_HANDSHAKE_FRAME_BYTES)
        );
        assert_eq!(
            code_of(HandshakeRequest::parse(&oversized)),
            ErrorCode::FrameTooLarge
        );
    }

    #[test]
    fn unknown_fields_are_ignored_for_the_future_envelope() {
        let request = HandshakeRequest::parse(
            r#"{"type":"authenticate","protocol_version":1,"request_id":"r1","device_id":"d","token":"t"}"#,
        )
        .unwrap();
        assert!(matches!(request, HandshakeRequest::Authenticate { .. }));
    }

    #[test]
    fn secrets_never_appear_in_debug_output_or_parse_errors() {
        let needle = "s3cr3t-value-zzz";
        let pair = HandshakeRequest::Pair {
            protocol_version: 1,
            method: PairingMethod::Credential,
            secret: Secret::new(needle),
            device_name: "phone".into(),
            install_id: None,
            wire_names: None,
            device_kind: None,
            platform: None,
            host_id: None,
        };
        let paired = HandshakeResponse::Paired {
            protocol_version: 1,
            gateway_id: "gw".into(),
            instance_id: "inst".into(),
            device_id: "dev".into(),
            device_name: "phone".into(),
            token: Secret::new(needle),
            host_name: Some("studio".into()),
            expires_at: None,
            wire_names: None,
        };
        assert!(!format!("{pair:?}").contains(needle));
        assert!(!format!("{paired:?}").contains(needle));
        assert!(!format!("{:?}", Secret::new(needle)).contains(needle));

        // A malformed frame that carries a secret is rejected without echoing it.
        let rejected = HandshakeRequest::parse(&format!(
            r#"{{"type":"authenticate","protocol_version":1,"token":"{needle}"}}"#
        ))
        .unwrap_err();
        assert!(!rejected.to_text().contains(needle));
        assert!(!format!("{rejected:?}").contains(needle));
    }
}
